module synchronizer(
    input clk_a, clk_b, arstn, brstn, data_en,
    input [3:0] data_in,
    output reg [3:0] dataout
);
    reg [3:0] data_reg;
    reg en_data_reg, en_clap_one, en_clap_two;
    // Data register
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            data_reg <= 4'd0;
        else
            data_reg <= data_in;
    end
    // Enable data register
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            en_data_reg <= 1'b0;
        else
            en_data_reg <= data_en;
    end
    // Enable control register 1
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            en_clap_one <= 1'b0;
        else
            en_clap_one <= en_data_reg;
    end
    // Enable control register 2
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            en_clap_two <= 1'b0;
        else
            en_clap_two <= en_clap_one;
    end
    // Output data
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            dataout <= 4'd0;
        else if (en_clap_two)
            dataout <= data_reg;
        else
            dataout <= dataout;
    end
endmodule
